initJs:
function(container, apiUrl, tables) {
  let currentModels = [];
  let currentStores = [];
  let selectedModel = null;
  let isProcessing = false;
  let progressInterval = null;

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-messages');
    errorDiv.innerHTML = `<div style="background: rgba(220, 53, 69, 0.1); border: 1px solid #dc3545; color: var(--text); padding: 1rem; border-radius: 4px; margin: 0.5rem 0;">${message}</div>`;
    setTimeout(() => errorDiv.innerHTML = '', 5000);
  }

  // ログ追加関数
  function addLog(message, type = 'info') {
    const logDisplay = container.querySelector('#log-display');
    const timestamp = new Date().toLocaleString();
    const color = type === 'error' ? '#dc3545' : type === 'success' ? '#28a745' : 'var(--text)';
    logDisplay.innerHTML += `<div style="color: ${color}; margin: 0.2rem 0;">[${timestamp}] ${message}</div>`;
    logDisplay.scrollTop = logDisplay.scrollHeight;
  }

  // モデル一覧の読み込み
  async function loadModels() {
    try {
      // 需要予測結果テーブルからモデルバージョンを取得
      const predictions = await window.aivicApi.list(9);
      if (predictions) {
        const modelVersions = [...new Set(predictions.map(p => p.予測モデルバージョン))];
        currentModels = modelVersions.map((version, index) => ({
          id: `model_${index}`,
          version: version,
          status: Math.random() > 0.3 ? '検証済み' : '検証中',
          accuracy: Math.floor(Math.random() * 20 + 80),
          created: new Date(Date.now() - Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString()
        }));
      }

      const modelSelect = container.querySelector('#model-select');
      modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>' +
        currentModels.map(model => 
          `<option value="${model.id}">${model.version} (精度: ${model.accuracy}%, ${model.status})</option>`
        ).join('');
    } catch (error) {
      showError('モデル一覧の読み込みに失敗しました');
    }
  }

  // 店舗一覧の読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1);
      if (stores) {
        currentStores = stores.filter(s => s.有効フラグ);
        const storeList = container.querySelector('#store-list');
        storeList.innerHTML = currentStores.map(store => 
          `<label style="display: block; margin: 0.3rem 0;">
            <input type="checkbox" class="store-checkbox" value="${store.店舗ID}"> 
            ${store.店舗名} (${store.店舗コード})
          </label>`
        ).join('');
      }
    } catch (error) {
      showError('店舗一覧の読み込みに失敗しました');
    }
  }

  // モデル詳細表示
  function showModelDetails(modelId) {
    const model = currentModels.find(m => m.id === modelId);
    if (!model) return;

    selectedModel = model;
    const detailsDiv = container.querySelector('#model-details');
    const infoDiv = container.querySelector('#model-info');

    infoDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
        <div><strong>モデルバージョン:</strong> ${model.version}</div>
        <div><strong>ステータス:</strong> ${model.status}</div>
        <div><strong>予測精度:</strong> ${model.accuracy}%</div>
        <div><strong>作成日時:</strong> ${new Date(model.created).toLocaleString()}</div>
      </div>
    `;
    detailsDiv.classList.remove('hidden');

    // 検証実行
    runValidation();
  }

  // 適用前検証実行
  function runValidation() {
    const validationDiv = container.querySelector('#validation-results');
    validationDiv.innerHTML = '<p style="color: var(--primary);">検証実行中...</p>';

    setTimeout(() => {
      const isValid = selectedModel && selectedModel.status === '検証済み' && selectedModel.accuracy >= 75;
      const validationHtml = `
        <div style="display: grid; gap: 0.5rem;">
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span style="color: ${isValid ? '#28a745' : '#dc3545'};">●</span>
            <span>データ品質チェック: ${isValid ? 'OK' : 'NG'}</span>
          </div>
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span style="color: ${selectedModel?.accuracy >= 80 ? '#28a745' : '#ffc107'};">●</span>
            <span>精度閾値チェック: ${selectedModel?.accuracy}% (閾値: 80%)</span>
          </div>
          <div style="display: flex; align-items: center; gap: 0.5rem;">
            <span style="color: #28a745;">●</span>
            <span>互換性チェック: OK</span>
          </div>
        </div>
      `;
      validationDiv.innerHTML = validationHtml;

      // 適用実行ボタンの状態更新
      updateExecuteButton();
    }, 1500);
  }

  // 影響範囲分析
  function updateImpactAnalysis() {
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const impactDiv = container.querySelector('#impact-analysis');

    if (selectedStores.length === 0) {
      impactDiv.innerHTML = '<p class="muted">適用対象を選択すると影響範囲が表示されます</p>';
      return;
    }

    const storeCount = selectedStores.length;
    const totalStores = currentStores.length;
    const impactPercentage = Math.round((storeCount / totalStores) * 100);

    impactDiv.innerHTML = `
      <div style="display: grid; gap: 0.5rem;">
        <div><strong>対象店舗数:</strong> ${storeCount} / ${totalStores} 店舗 (${impactPercentage}%)</div>
        <div><strong>予想処理時間:</strong> 約${Math.ceil(storeCount * 2)}分</div>
        <div><strong>影響する機能:</strong> 需要予測、自動発注、在庫管理</div>
        <div><strong>ダウンタイム:</strong> なし（無停止切替）</div>
      </div>
    `;

    updateExecuteButton();
  }

  // 適用実行ボタンの状態更新
  function updateExecuteButton() {
    const executeBtn = container.querySelector('#btn-execute');
    const selectedStores = container.querySelectorAll('.store-checkbox:checked');
    const startDateTime = container.querySelector('#start-datetime').value;
    const validationOk = selectedModel && selectedModel.status === '検証済み';

    const canExecute = selectedModel && selectedStores.length > 0 && startDateTime && validationOk && !isProcessing;
    executeBtn.disabled = !canExecute;
  }

  // 進捗バー更新
  function updateProgress(percentage, message) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');

    progressBar.style.width = `${percentage}%`;
    progressText.textContent = `${percentage}% - ${message}`;
  }

  // 適用実行処理
  async function executeDeployment() {
    if (!confirm('選択したモデルを本番環境に適用しますか？')) return;

    isProcessing = true;
    const executeBtn = container.querySelector('#btn-execute');
    const rollbackBtn = container.querySelector('#btn-rollback');
    const progressSection = container.querySelector('#progress-section');

    executeBtn.disabled = true;
    rollbackBtn.disabled = true;
    progressSection.classList.remove('hidden');

    addLog('モデル本番適用処理を開始します', 'info');

    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked'));
    const totalSteps = selectedStores.length * 3; // 各店舗で3ステップ
    let currentStep = 0;

    try {
      // バックアップ作成
      if (container.querySelector('#backup-setting').checked) {
        updateProgress(5, 'バックアップ作成中...');
        addLog('現行モデルのバックアップを作成中');
        await new Promise(resolve => setTimeout(resolve, 2000));
        addLog('バックアップ作成完了', 'success');
      }

      // 各店舗への適用
      for (const storeCheckbox of selectedStores) {
        const storeId = storeCheckbox.value;
        const store = currentStores.find(s => s.店舗ID === storeId);

        // ステップ1: モデル検証
        currentStep++;
        const progress1 = Math.floor((currentStep / totalSteps) * 80) + 10;
        updateProgress(progress1, `${store.店舗名}: モデル検証中...`);
        addLog(`${store.店舗名}: モデル検証を実行中`);
        await new Promise(resolve => setTimeout(resolve, 1000));

        // ステップ2: デプロイメント
        currentStep++;
        const progress2 = Math.floor((currentStep / totalSteps) * 80) + 10;
        updateProgress(progress2, `${store.店舗名}: デプロイ中...`);
        addLog(`${store.店舗名}: モデルデプロイメント実行中`);
        await new Promise(resolve => setTimeout(resolve, 1500));

        // ステップ3: 本番切替
        currentStep++;
        const progress3 = Math.floor((currentStep / totalSteps) * 80) + 10;
        updateProgress(progress3, `${store.店舗名}: 本番切替中...`);
        addLog(`${store.店舗名}: 本番環境への切替実行中`);
        await new Promise(resolve => setTimeout(resolve, 1000));

        addLog(`${store.店舗名}: 適用完了`, 'success');
      }

      // 最終確認
      updateProgress(95, '最終確認中...');
      addLog('全店舗への適用完了、最終確認実行中');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(100, '適用完了');
      addLog('モデル本番適用処理が正常に完了しました', 'success');

      rollbackBtn.disabled = false;

    } catch (error) {
      addLog(`エラーが発生しました: ${error.message}`, 'error');
      showError('適用処理中にエラーが発生しました');
    } finally {
      isProcessing = false;
      executeBtn.disabled = false;
    }
  }

  // ロールバック実行
  async function executeRollback() {
    if (!confirm('前のモデルにロールバックしますか？')) return;

    addLog('ロールバック処理を開始します', 'info');
    updateProgress(0, 'ロールバック準備中...');

    try {
      updateProgress(25, 'バックアップモデル確認中...');
      await new Promise(resolve => setTimeout(resolve, 1000));

      updateProgress(50, 'モデル切替中...');
      addLog('前バージョンモデルに切替中');
      await new Promise(resolve => setTimeout(resolve, 2000));

      updateProgress(75, '動作確認中...');
      addLog('ロールバック後の動作確認実行中');
      await new Promise(resolve => setTimeout(resolve, 1500));

      updateProgress(100, 'ロールバック完了');
      addLog('ロールバック処理が正常に完了しました', 'success');

    } catch (error) {
      addLog(`ロールバックエラー: ${error.message}`, 'error');
      showError('ロールバック処理中にエラーが発生しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#model-select').addEventListener('change', (e) => {
    if (e.target.value) {
      showModelDetails(e.target.value);
    } else {
      container.querySelector('#model-details').classList.add('hidden');
      selectedModel = null;
    }
    updateExecuteButton();
  });

  container.querySelector('#select-all-stores').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateImpactAnalysis();
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('store-checkbox')) {
      updateImpactAnalysis();
    }
    if (e.target.id === 'start-datetime') {
      const selectedDate = new Date(e.target.value);
      const now = new Date();
      if (selectedDate < now) {
        showError('適用開始日時には現在日時以降を指定してください');
        e.target.value = '';
      }
      updateExecuteButton();
    }
  });

  container.querySelector('#retention-period').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value < 1 || value > 9999) {
      showError('保持期間は1〜9999日の範囲で入力してください');
    }
  });

  container.querySelector('#btn-execute').addEventListener('click', executeDeployment);
  container.querySelector('#btn-rollback').addEventListener('click', executeRollback);

  // 初期化
  loadModels();
  loadStores();

  // 現在時刻を適用開始日時のデフォルトに設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#start-datetime').value = now.toISOString().slice(0, 16);
}
